content.css:
.visual-wrapper,
.criticalPathVisual,
.critical-path-tooltip,
.copy-toast,
.help-overlay {
  font-family: 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
.visual-wrapper *,
.criticalPathVisual *,
.visual-wrapper svg text,
.visual-wrapper svg tspan,
.criticalPathVisual text,
.criticalPathVisual tspan,
.critical-path-tooltip *,
.copy-toast *,
.help-overlay * {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
.criticalPathVisual {
  overflow: visible;
  max-width: none;
  flex-shrink: 0;
}
.sticky-header-container {
  pointer-events: none;
  contain: style;
}
.sticky-header-container > * {
  pointer-events: auto;
}
.visual-wrapper svg text,
.criticalPathVisual text {
  fill: #000000;
  dominant-baseline: middle;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
.task-duration-text {
  fill: #000000;
  font-size: 9px;
  font-weight: bold;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
}
.project-end-text {
  font-size: 11px;
  font-weight: bold;
  text-anchor: end;
}
.project-duration-text {
  font-size: 12px;
  font-weight: bold;
  text-anchor: middle;
}
.task-label {
  font-size: 11px;
}
.finish-date-label {
  font-size: 11px;
  text-anchor: start;
}
.milestone-shape {
  stroke: #000000;
  stroke-width: 1px;
}
.task-bar {
  stroke: #000000;
  stroke-width: 0.5px;
}
.visual-wrapper.live-geometry-paint .task-layer .task-bar,
.visual-wrapper.live-geometry-paint .task-layer .milestone,
.visual-wrapper.live-geometry-paint .task-layer .date-background {
  filter: none !important;
}
.dependency-arrow {
  stroke-width: 1.5px;
  fill: none;
}
.dependency-arrow-critical {
  stroke-width: 2px;
}
.project-end-line,
.baseline-end-line,
.previous-update-end-line,
.aphex-end-line {
  vector-effect: non-scaling-stroke;
}
.finish-marker-collision-caps,
.comparison-finish-key-layer {
  pointer-events: none;
}
.comparison-finish-key-chip {
  pointer-events: all;
  cursor: help;
}
.timeline-zoom-slider-container {
  font-family: 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  box-sizing: border-box;
  transition: height 0.2s ease, opacity 0.2s ease;
}
.timeline-zoom-slider-container.dragging {
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
}
.zoom-slider-track {
  box-sizing: border-box;
  transition: left 0.15s ease, right 0.15s ease;
}
.zoom-slider-selection {
  transition: background-color 0.15s ease, left 0.05s ease, width 0.05s ease;
}
.zoom-slider-selection:active {
  cursor: grabbing;
}
.zoom-slider-selection:focus-visible,
.zoom-slider-handle:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 3px;
}
.zoom-slider-handle {
  transition: background-color 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}
.zoom-slider-handle:hover {
  transform: translate(-50%, -50%) scale(1.2);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}
.zoom-slider-handle:active {
  transform: translate(-50%, -50%) scale(1.1);
}
.zoom-slider-handle-left:hover {
  transform: translate(-50%, -50%) scale(1.2);
}
.zoom-slider-handle-left:active {
  transform: translate(-50%, -50%) scale(1.1);
}
.zoom-slider-handle-right:hover {
  transform: translate(50%, -50%) scale(1.2);
}
.zoom-slider-handle-right:active {
  transform: translate(50%, -50%) scale(1.1);
}
.zoom-slider-mini-chart {
  image-rendering: auto;
}
.legend-main {
  display: flex;
  align-items: center;
  height: 100%;
  width: 100%;
  padding: 8px 12px;
  gap: 0;
  box-sizing: border-box;
  font-family: inherit;
  color: #000000;
}
.legend-scroll-wrapper {
  flex: 1;
  overflow-x: auto;
  overflow-y: hidden;
  position: relative;
  scrollbar-width: none;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
}
.legend-scroll-wrapper::-webkit-scrollbar {
  display: none;
}
.legend-scroll-content {
  display: flex;
  gap: 20px;
  align-items: center;
  transition: none;
  padding: 5px 0;
}
.legend-scroll-arrow {
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background-color: #f0f0f0;
  border-radius: 4px;
  user-select: none;
  transition: background-color 0.2s, transform 0.2s, opacity 0.2s;
  color: #444444;
  font-size: 14px;
  line-height: 1;
}
.legend-scroll-arrow.is-disabled {
  opacity: 0.3;
  cursor: default;
  pointer-events: none;
}
.legend-scroll-arrow:not(.is-disabled):hover {
  background-color: #e0e0e0;
}
.legend-scroll-arrow:focus {
  outline: 2px solid #005A9E;
  outline-offset: 2px;
}
.legend-scroll-left {
  margin-right: 10px;
}
.legend-scroll-right {
  margin-left: 10px;
}
.legend-title {
  font-weight: 600;
  color: #000000;
  white-space: normal;
  overflow-wrap: anywhere;
  margin-right: 0;
}
.legend-count {
  color: #444444;
  white-space: nowrap;
  margin-right: 15px;
  padding: 2px 8px;
  background-color: #f0f0f0;
  border-radius: 10px;
}
.legend-item {
  appearance: none;
  font: inherit;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  cursor: pointer;
  user-select: none;
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid var(--legend-item-border, var(--lpv-header-legend-border-color, #767676));
  transition: opacity 0.2s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  opacity: var(--legend-item-opacity, 1);
  background-color: var(--legend-item-background, transparent);
  box-shadow: none;
}
.legend-item.is-selected {
  opacity: 1;
  border-color: var(--legend-item-border, var(--lpv-header-legend-border-color, #767676));
}
.legend-item:hover {
  opacity: 1;
  background-color: var(--legend-item-hover-background, var(--lpv-header-legend-hover-background-color, #D1D5DB));
  border-color: var(--legend-item-hover-border, var(--lpv-header-legend-border-color, #767676));
  box-shadow: none;
  outline: 1px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: -1px;
}
.legend-item:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: -2px;
}
.legend-action-button:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: -2px;
}
.legend-status-reset:not(:disabled):hover {
  outline: 1px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: -1px;
}
.legend-action-button {
  appearance: none;
  font-family: inherit;
}
.legend-action-button:disabled,
.legend-item:disabled {
  pointer-events: none;
}
.legend-swatch {
  width: 16px;
  height: 16px;
  background-color: var(--legend-color, #999);
  border: 2px solid #ccc;
  border-radius: 3px;
  flex-shrink: 0;
  transition: border-color 0.2s;
}
.legend-item.is-selected .legend-swatch {
  border-color: var(--legend-color, #999);
}
.legend-label {
  white-space: pre;
  font-weight: 400;
  text-decoration: line-through;
}
.legend-item.is-selected .legend-label {
  font-weight: 500;
  text-decoration: none;
}
@media (prefers-reduced-motion: reduce) {
  .visual-wrapper,
  .visual-wrapper *,
  .help-overlay,
  .help-overlay *,
  .copy-toast {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
  .timeline-zoom-slider-container,
  .timeline-zoom-slider-selection,
  .legend-scroll-content,
  .legend-item,
  .legend-swatch,
  .legend-scroll-arrow {
    transition: none !important;
    animation: none !important;
  }
  .loading-overlay .initial-load-progress-line {
    animation: none !important;
    transform: none !important;
    width: 50% !important;
  }
}
.task-label-truncated {
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}
.float-label {
  font-family: 'Segoe UI Semibold', 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  pointer-events: none;
}
.float-column-header {
  font-size: 9px;
  font-weight: 600;
  fill: #000000;
  text-anchor: end;
  dominant-baseline: hanging;
}
.skeleton-loading {
  position: relative;
  overflow: hidden;
  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.5s ease-in-out infinite;
}
@keyframes skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
.skeleton-task-bar {
  height: 20px;
  border-radius: 4px;
  margin: 4px 0;
}
.skeleton-task-label {
  height: 12px;
  border-radius: 2px;
  width: 60%;
}
.driving-connector {
  stroke-dasharray: none;
}
.non-driving-connector {
  stroke-dasharray: 6, 4;
  opacity: 0.4;
}
.relationship-arrow.negative-float.non-driving {
  stroke-dasharray: 3, 3;
}
.relationship-arrow:focus-visible {
  outline: none;
  filter: drop-shadow(0 0 2px currentColor);
}
.wbs-group-header {
  outline: none;
}
.column-header-sortable {
  cursor: pointer;
  outline: none;
}
.column-header-sortable[aria-disabled="true"] {
  cursor: default;
}
.column-header-hit,
.column-header-focus {
  vector-effect: non-scaling-stroke;
}
.column-header-hit {
  fill: transparent;
  stroke: transparent;
}
.column-header-sortable:not([aria-disabled="true"]):hover .column-header-hit {
  fill: var(--lpv-header-legend-hover-background-color, rgba(0, 90, 158, 0.12));
  fill-opacity: 0.55;
  stroke: var(--lpv-focus-outline-color, #005A9E);
  stroke-width: 1px;
}
.column-header-focus {
  fill: none;
  stroke: transparent;
  pointer-events: none;
}
.column-header-sortable:focus-visible .column-header-focus {
  stroke: var(--lpv-focus-outline-color, #005A9E);
  stroke-width: 2px;
}
.column-header-text,
.column-sort-indicator {
  pointer-events: none;
  user-select: none;
}
.toggle-button:focus-visible,
.header-button:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 2px;
}
.task-label:hover {
  cursor: pointer;
  text-decoration: underline;
}
.float-label:hover {
  opacity: 1 !important;
}
.task-selection-item:hover {
  background-color: #f3f2f1;
}
.task-selection-item.active {
  background-color: #edebe9;
}
@media (forced-colors: active) {
  .column-header-sortable {
    forced-color-adjust: auto;
  }
  .column-header-sortable:not([aria-disabled="true"]):hover .column-header-hit {
    fill: Highlight;
    fill-opacity: 0.25;
    stroke: Highlight;
  }
  .column-header-sortable:focus-visible .column-header-focus {
    stroke: Highlight;
  }
  .column-sort-indicator {
    fill: ButtonText !important;
  }
  .legend-swatch {
    forced-color-adjust: none;
  }
  .timeline-zoom-slider-selection {
    border: 2px solid CanvasText;
  }
  .task-bar,
  .milestone-shape {
    stroke: CanvasText;
  }
}
@keyframes export-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.export-button-group {
  transition: opacity 0.2s ease;
}
.export-button-group.is-exporting {
  cursor: wait !important;
  pointer-events: none;
}
.export-button-group .export-spinner {
  transform-origin: center;
  animation: export-spin 1s linear infinite;
}
.export-button-group:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 2px;
}
.header-toggle-button {
  position: absolute;
  padding: 0;
  box-sizing: border-box;
  will-change: auto;
  border-style: solid;
  border-radius: 4px;
  box-shadow: 0 1.6px 3.6px 0 rgba(0, 0, 0, 0.132), 0 0.3px 0.9px 0 rgba(0, 0, 0, 0.108);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s cubic-bezier(0.33, 1, 0.68, 1);
}
.header-toggle-button.is-disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}
.header-toggle-button:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 2px;
}
.action-overflow-menu button:focus-visible,
.action-overflow-menu input:focus-visible,
.action-overflow-menu select:focus-visible,
.action-overflow-menu [tabindex="0"]:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 1px;
}
.aphex-comparison-control-wrapper select:focus-visible,
.aphex-comparison-control-wrapper input:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 1px;
}
.look-ahead-control-button:focus-visible,
.look-ahead-option-list .look-ahead-option-button:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 1px;
}
.toggle-text {
  font-family: 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-size: 14px;
  fill: #000000;
  pointer-events: none;
}
.look-ahead-option-list {
  scrollbar-width: thin;
  scrollbar-color: #6F7A8C transparent;
}
.look-ahead-option-list::-webkit-scrollbar {
  width: 5px;
}
.look-ahead-option-list::-webkit-scrollbar-track {
  background: transparent;
}
.look-ahead-option-list::-webkit-scrollbar-thumb {
  background-color: #6F7A8C;
  border-radius: 999px;
}
.look-ahead-option-list::-webkit-scrollbar-button {
  width: 0;
  height: 0;
  display: none;
}
.task-selection-dropdown-container {
  position: absolute;
  top: 10px;
  left: 150px;
  z-index: 20;
  display: none;
}
.task-selection-input {
  width: 250px;
  padding: 5px 8px;
  border: 1px solid var(--lpv-header-legend-border-color, #767676);
  border-radius: 4px;
  font-family: 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-size: 9px;
  color: #000000;
}
.task-selection-input:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 2px;
}
.task-selection-input:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}
.task-selection-list {
  max-height: 150px;
  overflow-y: auto;
  width: 100%;
  background: #FFFFFF;
  border: 1px solid var(--lpv-header-legend-border-color, #767676);
  border-top: none;
  border-radius: 0 0 4px 4px;
  box-shadow: none;
  display: none;
  z-index: 30;
  pointer-events: auto;
  margin-bottom: 40px;
}
.dropdown-item-primary {
  min-width: 0;
}
.dropdown-item-secondary {
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.25;
}
.dropdown-item.filter .dropdown-item-primary,
.dropdown-item.clear .dropdown-item-primary {
  font-weight: 600;
}
@media (forced-colors: active) {
  .task-selection-input:focus-visible {
    outline-color: Highlight;
  }
  .task-selection-input,
  .task-selection-list,
  .dropdown-item {
    forced-color-adjust: auto;
  }
}
.selected-task-label {
  position: absolute;
  top: 10px;
  right: 15px;
  padding: 5px 10px;
  background-color: rgba(255, 255, 255, 0.8);
  border: 1px solid var(--lpv-header-legend-border-color, #767676);
  border-radius: 4px;
  font-family: 'Segoe UI', wf_segoe-ui_normal, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  font-size: 9px;
  color: #000000;
  font-weight: bold;
  display: none;
}
.loading-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: none;
  background: #ffffff;
  z-index: 50;
  pointer-events: none;
}
.aphex-inline-status {
  position: absolute;
  right: 6px;
  z-index: 90;
  box-sizing: border-box;
  min-height: 24px;
  align-items: center;
  gap: 4px;
  overflow: hidden;
  padding: 3px 8px;
  border: 1px solid var(--lpv-header-legend-border-color, #767676);
  border-radius: 4px;
  background: var(--lpv-header-legend-control-background-color, #FFFFFF);
  color: var(--aphex-inline-status-text, #242424);
  box-shadow: none;
  font-size: 10px;
  font-weight: 600;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: auto;
}
.aphex-inline-status.is-warning {
  border-color: var(--aphex-inline-warning-color, #7A3E00);
  background: var(--aphex-inline-warning-background, #FFF4CE);
  color: var(--aphex-inline-warning-text, #5C2D00);
}
.aphex-inline-status.is-focus {
  font-weight: 700;
}
.aphex-inline-status-summary {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.aphex-inline-status-return {
  flex: 0 0 auto;
  padding-left: 6px;
  border-left: 1px solid currentColor;
}
.aphex-inline-status[aria-disabled="true"] {
  opacity: 0.72;
}
.aphex-inline-status.is-focus:not([aria-disabled="true"]):hover {
  text-decoration: underline;
  text-underline-offset: 2px;
}
.aphex-inline-status:focus-visible {
  outline: 2px solid var(--lpv-focus-outline-color, #005A9E);
  outline-offset: 1px;
}
.aphex-inline-row-background {
  fill: var(--aphex-inline-row-background-color, #005A9E);
  fill-opacity: var(--aphex-inline-row-background-opacity, 0.2);
  stroke: var(--aphex-inline-row-border-color, #767676);
  stroke-width: 0.5px;
  stroke-opacity: 0.2;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
.aphex-inline-row-background.is-hovered {
  fill-opacity: var(--aphex-inline-row-background-hover-opacity, 0.2);
  stroke-width: 1px;
  stroke-opacity: 0.75;
}
.aphex-inline-task-row {
  opacity: 0.86;
}
.aphex-inline-hit-target {
  cursor: help;
  pointer-events: all;
}
.aphex-inline-bar {
  fill-opacity: 0.8;
  shape-rendering: geometricPrecision;
  vector-effect: non-scaling-stroke;
  filter: none;
}
.aphex-inline-offscreen-cue {
  fill-opacity: 0.9;
  stroke: var(--aphex-inline-bar-outline-color, #0F6CBD);
  stroke-width: 0.75px;
  vector-effect: non-scaling-stroke;
  filter: none;
}
.aphex-inline-clipped-cue {
  stroke: var(--aphex-inline-warning-color, #7A3E00);
  stroke-width: 1.5px;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}
.aphex-inline-date-warning,
.aphex-inline-label-warning {
  fill: var(--aphex-inline-warning-color, #7A3E00);
  font-weight: 700;
}
.aphex-inline-date-warning {
  font-size: 10px;
}
.aphex-inline-label-layer {
  isolation: isolate;
}
.aphex-inline-label-row {
  cursor: help;
  outline: none;
}
.aphex-inline-focus-ring {
  fill: var(--aphex-inline-accent-color, #0F6CBD);
  fill-opacity: 0;
  stroke: transparent;
  stroke-width: 0;
  vector-effect: non-scaling-stroke;
  pointer-events: all;
  transition: fill-opacity 120ms ease, stroke 120ms ease, stroke-width 120ms ease;
}
.aphex-inline-label-row:hover .aphex-inline-focus-ring {
  fill-opacity: 0.055;
}
.aphex-inline-label-row.is-keyboard-focused .aphex-inline-focus-ring,
.aphex-inline-label-row:focus-visible .aphex-inline-focus-ring {
  fill-opacity: 0.08;
  stroke: var(--lpv-focus-outline-color, #005A9E);
  stroke-width: 2px;
}
.aphex-inline-branch {
  stroke: var(--aphex-inline-accent-color, #0F6CBD);
  stroke-width: 1px;
  stroke-opacity: 0.55;
  stroke-dasharray: 2 2;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
.aphex-parent-hierarchy-link,
.aphex-parent-hierarchy-chevron {
  fill: none;
  stroke: var(--aphex-inline-accent-color, #0F6CBD);
